import os
import time
import boto3

def poll_transcription(payload, config=None):
    config = config or {}
    transcribe = boto3.client('transcribe',
        aws_access_key_id=config.get('AWS_ACCESS_KEY_ID', os.getenv('AWS_ACCESS_KEY_ID')),
        aws_secret_access_key=config.get('AWS_SECRET_ACCESS_KEY', os.getenv('AWS_SECRET_ACCESS_KEY')),
        region_name=config.get('AWS_REGION', os.getenv('AWS_REGION', 'us-east-1'))
    )

    job_name = payload.get('job_name')
    if not job_name:
        raise ValueError("job_name is required in payload")

    while True:
        response = transcribe.get_transcription_job(TranscriptionJobName=job_name)
        status = response['TranscriptionJob']['TranscriptionJobStatus']
        if status in ['COMPLETED', 'FAILED']:
            break
        time.sleep(5)

    result = {
        'status': status,
        'transcript': response['TranscriptionJob'].get('Transcript', {}).get('TranscriptFileUri')
    }
    if status == 'COMPLETED':
        import requests
        transcript_response = requests.get(result['transcript'])
        result['transcript'] = transcript_response.json()['results']['transcripts'][0]['transcript']
    return result
